"""Export the actual Pydantic contract, rather than a separately maintained schema."""

from pathlib import Path

import yaml

from catalyst_ai.schemas.domain import ImportRecord


def main():
    output = Path(__file__).resolve().parents[1] / "configs/data_schema.yaml"
    schema = {
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        **ImportRecord.model_json_schema(),
    }
    output.write_text(
        "# Generated by scripts/generate_schema.py; do not edit manually.\n"
        + yaml.safe_dump(schema, allow_unicode=True, sort_keys=False),
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
